<script setup>
import {ref,computed,reactive,onMounted,onBeforeUnmount} from 'vue'
import Chart from './Chart.vue'
import BasinMap from './Map.vue'
const pages=[['overview','◈','湖情总览'],['monitor','≋','监测资料'],['simulation','▷','历史模拟'],['calibration','⌘','参数率定'],['process','⊞','过程与状态'],['results','▥','计算成果'],['model','◇','模型与资料'],['system','⚙','工作区与系统']]
const page=ref(localStorage.getItem('selinco:page')||'overview'),boot=ref(null),tasks=ref([]),states=ref([]),system=ref(null),detail=ref(null),compare=ref(null),observations=ref([]),obsDaily=ref([]),mainLevel=ref([]),processRows=ref([]),unit=ref(0),error=ref(''),notice=ref(''),busy=ref(false),trash=ref(false),paramName=ref(''),schemeName=ref(''),restoreFile=ref(''),restorePreview=ref(null),cleanup=ref(null),selectedState=ref('')
const params=reactive({}),run=reactive({name:'',inputId:'',start:'2023-01-01T00:00',end:'2025-12-31T23:00',stage:'runoff',maxEvaluations:120,seed:42,baseTaskId:''}),monitor=reactive({station:'SLC',variable:'level',step:'',start:'2024-01-01',end:'2026-12-31'}),uploadFile=ref(null),uploadStation=ref('SLC'),viewTab=ref('daily'),coverageEdit=reactive({sourceId:'',start:'',end:'',stops:'',note:''})
const inputFiles=ref([]),selectedFiles=ref([]),climateRows=ref([])
let timer
const title=computed(()=>pages.find(p=>p[0]===page.value)?.[2]||'湖情总览')
const active=computed(()=>tasks.value.filter(t=>['queued','running','stopping'].includes(t.status)))
const completed=computed(()=>tasks.value.filter(t=>t.status==='succeeded'&&['simulation','trial','continuation','calibration'].includes(t.kind)))
const listed=computed(()=>tasks.value.filter(t=>!!t.trashed===trash.value))
const stationName=id=>boot.value?.stations.find(s=>s.id===id)?.name||id
const status=s=>({queued:'排队',running:'运行中',stopping:'停止中',succeeded:'已完成',cancelled:'已停止',failed:'失败',interrupted:'已中断'}[s]||s)
const number=(v,n=2)=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:n})
const latest=computed(()=>mainLevel.value.at(-1))
const resultSeries=computed(()=>[{key:'lakeLevel',label:'模拟湖位'},{key:'observedLevel',label:'主站实测'}])
const comparedRows=computed(()=>{if(!detail.value?.result)return[];const other=new Map((compare.value?.result?.daily||[]).map(r=>[r.date,r]));return detail.value.result.daily.map(r=>({...r,comparedLake:other.get(r.date)?.lakeLevel,comparedFlow:other.get(r.date)?.duja}))})
async function api(path,body,method){const r=await fetch('/api/model/'+path,{method:method||(body?'POST':'GET'),headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(data.error||'请求失败');return data}
async function action(fn){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function navigate(p){page.value=p;localStorage.setItem('selinco:page',p);error.value='';if(p==='monitor')loadObservations();if(p==='system')loadSystem();if(p==='model')action(loadInputFiles)}
async function loadInputFiles(){inputFiles.value=(await api('input-files')).files}
async function registerFiles(){await action(async()=>{await api('tasks',{kind:'register-inputs',files:selectedFiles.value});notice.value='气象登记任务已提交；所选文件须连续覆盖';await refresh()})}
async function loadClimate(){await action(async()=>{climateRows.value=(await api('input-series?inputId='+run.inputId)).rows})}
async function refresh(){boot.value=await api('bootstrap');tasks.value=(await api('tasks')).tasks;states.value=(await api('states')).states;if(!run.inputId&&boot.value.inputs.some(i=>i.compatible!==false))chooseInput(preferredInput().id);if(!Object.keys(params).length)Object.assign(params,boot.value.defaultParameters);if(detail.value&&active.value.some(t=>t.id===detail.value.id))detail.value=await api('tasks/'+detail.value.id)}
function chooseInput(id){run.inputId=id;const i=boot.value.inputs.find(x=>x.id===id)?.manifest;if(i){run.start=i.start.slice(0,16);run.end=i.end.slice(0,16)}}
async function submit(kind){await action(async()=>{const request={...run,kind,parameters:{...params},calibrationYear:2024};if(kind==='continuation')request.stateId=selectedState.value;const t=await api('tasks',request);detail.value=t;notice.value='任务已提交，进度将自动更新';await refresh()})}
async function operation(kind){await action(async()=>{await api('tasks',{kind});notice.value='后台任务已提交';await refresh()})}
async function openTask(id){await action(async()=>{detail.value=await api('tasks/'+id);unit.value=0;if(page.value==='process')await loadProcess()})}
async function loadObservations(){await action(async()=>{const q=new URLSearchParams({...monitor,limit:'3000'});observations.value=(await api('observations?'+q)).rows;obsDaily.value=(await api('observation-series?'+q)).rows})}
async function loadProcess(){if(detail.value?.status!=='succeeded')return;await action(async()=>{processRows.value=(await api(`process?taskId=${detail.value.id}&unit=${unit.value}`)).rows})}
async function loadSystem(){await action(async()=>{system.value=await api('system')})}
async function stop(id){await action(async()=>{await api(`tasks/${id}/stop`,{});await refresh()})}
async function metadata(task,change){await action(async()=>{await api(`tasks/${task.id}/metadata`,change);await refresh()})}
async function saveParameters(){await action(async()=>{await api('parameters',{name:paramName.value,payload:{parameters:{...params},sourceTaskId:detail.value?.result&&JSON.stringify(params)===JSON.stringify(detail.value.result.parameters)?detail.value.id:undefined,provenance:'用户命名参数'}});notice.value='参数版本已保存';await refresh()})}
async function saveScheme(){await action(async()=>{await api('schemes',{name:schemeName.value,payload:{...run,parameters:{...params}}});notice.value='方案已保存';await refresh()})}
function useResult(){if(detail.value?.result){Object.assign(params,detail.value.result.parameters);run.baseTaskId=detail.value.id;run.inputId=detail.value.result.inputId;notice.value='已恢复成果参数和输入版本，可试调或作为湖泊率定基准'}}
function restoreRequest(){const t=detail.value;if(!t?.request?.parameters)return;Object.assign(run,t.request);Object.assign(params,t.request.parameters);run.name=(t.name||'历史任务')+'-重算';page.value=t.kind==='calibration'?'calibration':'simulation';notice.value='已恢复任务的输入版本、参数和时段；新任务将记录当前评价资料快照'}
function preferredInput(){const list=boot.value.inputs.filter(i=>i.compatible!==false);return list.find(i=>i.manifest.start<='2023-01-01T00:00:00'&&i.manifest.end>='2023-05-01T00:00:00')||list[0]}
async function upload(){await action(async()=>{if(!uploadFile.value)throw Error('请先选择文件');const f=uploadFile.value;const r=await fetch(`/api/model/upload?filename=${encodeURIComponent(f.name)}&station=${uploadStation.value}`,{method:'PUT',body:f});const d=await r.json();if(!r.ok)throw Error(d.error);if(f.name.endsWith('.zip')){restoreFile.value=d.filename;restorePreview.value=await api('restore-preview',{filename:d.filename});notice.value='已扫描备份，请核对恢复清单'}else{notice.value='上传完成；请扫描预览或登记输入';if(/\.xlsx?$/.test(f.name))await previewImport()}})}
async function previewImport(){const d=await api('import-preview');notice.value=`扫描 ${d.files.length} 个文件；可识别 ${d.files.filter(f=>f.status==='ready').length} 个观测文件。点击“校验并入库”开始。`}
async function backup(){await action(async()=>{const d=await api('backup',{});notice.value=`备份完成：${d.files} 个文件，${number(d.bytes/1024/1024)} MB`;window.location.href='/api/model/download?filename='+encodeURIComponent(d.filename)})}
async function restore(){await action(async()=>{const d=await api('restore',{filename:restoreFile.value,token:restorePreview.value.token});notice.value=d.message;restorePreview.value=null})}
async function previewCleanup(t){await action(async()=>{cleanup.value=await api(`tasks/${t.id}/cleanup-preview`,{})})}
async function executeCleanup(){await action(async()=>{await api(`tasks/${cleanup.value.taskId}/cleanup-execute`,{token:cleanup.value.token});cleanup.value=null;notice.value='文件已移入Windows回收站';await refresh()})}
async function resume(s){await action(async()=>{selectedState.value=s.id;const checkpoint=(await api('states/'+s.id)).state;Object.assign(params,checkpoint.parameters);run.inputId=checkpoint.identity.inputId;run.start=new Date(Date.parse(s.valid_at+'Z')+3600000).toISOString().slice(0,16);const input=boot.value.inputs.find(i=>i.id===run.inputId);if(input)run.end=input.manifest.end.slice(0,16);notice.value='已恢复状态对应的输入与参数；从状态下一小时续算';page.value='process'})}
async function confirmCoverage(){await action(async()=>{await api('coverage',{...coverageEdit,station:monitor.station,variable:monitor.variable});notice.value='观测覆盖已确认，停测区间保留为未知';await refresh();await loadObservations()})}
const exportUrl=(f)=>`/api/model/export?taskId=${detail.value?.id}&format=${f}`
onMounted(async()=>{await action(async()=>{await refresh();mainLevel.value=(await api('observation-series?station=SLC&variable=level')).rows;if(page.value==='model')await loadInputFiles();if(page.value==='monitor')await loadObservations();if(page.value==='system')await loadSystem()});timer=setInterval(async()=>{try{const old=active.value.map(t=>t.id);tasks.value=(await api('tasks')).tasks;if(old.some(id=>!active.value.some(t=>t.id===id))){await refresh();if(detail.value&&old.includes(detail.value.id))detail.value=await api('tasks/'+detail.value.id)}}catch(e){error.value=e.message}},2500)});onBeforeUnmount(()=>clearInterval(timer))
</script>

<template>
<div class="app-shell">
 <aside class="sidebar"><div class="brand"><span class="brand-mark">◈</span><div>色林错<span>预警预报平台</span></div></div><div class="project-tag"><i></i> SELINCO / 独立工作区</div><nav><button v-for="p in pages" :key="p[0]" :class="{selected:page===p[0]}" @click="navigate(p[0])"><span>{{p[1]}}</span>{{p[2]}}<small v-if="p[0]==='results'&&active.length">{{active.length}}</small></button></nav><div class="sidebar-bottom"><span>半分布式新安江 · 冰雪过程</span><strong>历史计算版 <b>v{{boot?.version||'0.1.0'}}</b></strong></div></aside>
 <main><header><div><span class="breadcrumb">色林错流域 <span>/</span> {{title}}</span><h1>{{title}}</h1></div><div class="header-right"><span class="pill"><i></i>{{boot?'本地服务已连接':'正在连接'}}</span><button class="quiet" @click="action(refresh)">↻ 刷新</button></div></header>
 <div class="content"><div v-if="error" class="message error" role="alert">{{error}}<button @click="error=''">×</button></div><div v-if="notice" class="message success" role="status">{{notice}}<button @click="notice=''">×</button></div>
 <div v-if="!boot" class="panel empty">正在读取色林错工作区…</div>
 <template v-else>
 <div v-if="active.length" class="running-strip"><i></i>{{active[0].name||'后台任务'}} · {{active[0].message||status(active[0].status)}}<progress :value="active[0].progress" max="100"></progress><span>{{number(active[0].progress,1)}}%</span><button @click="stop(active[0].id)">停止任务</button></div>
 <template v-if="page==='overview'">
  <div class="intro"><div><h2>监测与历史计算，一处掌握</h2><p>多源监测 → 流域来水模拟 → 湖泊水量平衡 → 湖位预测</p></div><button class="primary" @click="navigate('simulation')">开展历史模拟 ↗</button></div>
  <div class="stats"><div class="stat"><span>主站最近可靠日水位 <em>m</em></span><strong>{{number(latest?.value,3)}}</strong><small>{{latest?.time?.slice(0,10)||'暂无可靠资料'}} · 观测值</small></div><div class="stat"><span>定面积湖面 <em>km²</em></span><strong>{{number(boot.spatial?.lakeAreaKm2)}}</strong><small>由现有湖泊边界核算</small></div><div class="stat"><span>完整冰川面积 <em>km²</em></span><strong>{{number(boot.spatial?.glacierAreaKm2)}}</strong><small>{{boot.spatial?.glacierCount}} 个冰川要素 · 已去重</small></div><div class="stat"><span>资料与计算单元</span><strong>{{boot.database.counts.stations}} <em>站</em><span class="stat-divider">/</span>{{boot.spatial?.units.length}} <em>单元</em></strong><small>{{number(boot.database.counts.observations,0)}} 条原始记录</small></div></div>
  <div class="overview-grid"><section class="panel map-panel"><div class="panel-title"><h3>流域空间总览</h3><span>四河 + 湖周补充汇水区</span></div><BasinMap/><div class="map-caption">控制域 {{number(boot.spatial?.domainAreaKm2)}} km² · 杜加控制区 {{number(boot.spatial?.duja.areaKm2)}} km²</div></section><div class="overview-side"><section class="panel"><div class="panel-title"><h3>业务链状态</h3><span class="badge">历史闭环</span></div><div class="chain"><div><b>01</b><section><strong>多源资料管理</strong><p>{{boot.database.counts.sources}} 份来源文件 · 原始标记可追溯</p></section><i>✓</i></div><div><b>02</b><section><strong>流域与冰雪产汇流</strong><p>0.1°气象 · 500 m高程带 · 小时演算</p></section><i>✓</i></div><div><b>03</b><section><strong>湖泊水量平衡</strong><p>定面积 · 可靠观测窗口起算</p></section><i>✓</i></div><div><b>04</b><section><strong>7—15 天滚动预报</strong><p>下一阶段接入未来气象与最新状态</p></section><span class="muted">待接入</span></div></div></section><section class="panel"><div class="panel-title"><h3>当前可用资料</h3></div><div class="availability"><span>观测资料</span><b>{{boot.database.counts.observations?'已入库':'待导入'}}</b></div><div class="availability"><span>真实气象输入</span><b>{{boot.inputs.length?boot.inputs.length+' 个版本':'待登记'}}</b></div><p class="note warning" v-if="boot.annualValidation&&!boot.annualValidation.ready">{{boot.annualValidation.message}}</p><p class="note">{{boot.inputs[0]?boot.inputs[0].manifest.start.slice(0,10)+' 至 '+boot.inputs[0].manifest.end.slice(0,10):'下载或导入 ERA5-Land 后可开展历史计算。'}}</p></section></div></div>
  <section class="panel"><div class="panel-title"><h3>主站历史湖位</h3><span>可靠日值 · 四岸水位分别管理</span><button class="link" @click="navigate('monitor')">查看监测资料 →</button></div><Chart :rows="mainLevel" :series="[{key:'value',label:'主站实测湖位'}]" unit="m"/></section>
 </template>
 <template v-if="page==='monitor'">
  <section class="panel"><div class="panel-title"><h3>监测资料查询</h3><span>原始时间、文字和质量标记完整保留</span></div><div class="form-row"><label>站点<select v-model="monitor.station"><option v-for="s in boot.stations" :value="s.id">{{s.name}}</option></select></label><label>变量<select v-model="monitor.variable"><option value="level">水位 / m</option><option value="flow">流量 / m³/s</option><option value="precipitation">降水 / mm</option><option value="temperature">气温 / ℃</option><option value="evaporation">蒸发 / mm</option><option value="area">湖面面积 / km²</option><option value="snow">积雪</option></select></label><label>起始日期<input type="date" v-model="monitor.start"></label><label>结束日期<input type="date" v-model="monitor.end"></label><button class="primary" @click="loadObservations">查询</button></div><Chart :rows="obsDaily" :series="[{key:'value',label:stationName(monitor.station)}]" :unit="monitor.variable==='level'?'m':monitor.variable==='flow'?'m³/s':'mm'"/><p class="note">四岸基准尚未统一，不平均替代主站。冬季零流量标为待复核；雨量仅在已确认覆盖期内补零。</p></section>
  <section class="panel"><div class="panel-title"><h3>原始观测记录</h3><span>最多展示 3,000 条，完整记录保存在 SQLite</span></div><div class="table-wrap"><table><thead><tr><th>原始时间</th><th>时段</th><th>数值</th><th>原始文本</th><th>质量标记</th><th>来源 / 工作表 / 位置</th></tr></thead><tbody><tr v-for="r in observations" :key="r.id"><td>{{r.time.replace('T',' ')}}</td><td>{{r.step}}</td><td>{{r.value??'—'}} {{r.unit}}</td><td>{{r.raw_text}}</td><td><span class="badge" :class="{warning:r.quality!=='valid'}">{{r.quality}}</span></td><td>{{r.source_id.slice(-8)}} / {{r.sheet}} / {{r.cell}}</td></tr><tr v-if="!observations.length"><td colspan="6" class="empty">此条件下没有观测记录</td></tr></tbody></table></div></section>
  <section class="panel"><div class="panel-title"><h3>覆盖范围与停测区间</h3></div><div class="table-wrap"><table><thead><tr><th>站点 / 变量</th><th>起止</th><th>有效 / 总数</th><th>覆盖确认</th></tr></thead><tbody><tr v-for="c in boot.database.coverage.filter(c=>c.station_id===monitor.station&&c.variable===monitor.variable)"><td>{{stationName(c.station_id)}} / {{c.step}}</td><td>{{c.start}} — {{c.end}}</td><td>{{c.valid}} / {{c.total}}</td><td>{{c.metadata.coverageConfirmed?'已确认':'待核对'}} <button class="link" @click="Object.assign(coverageEdit,{sourceId:c.source_id,start:c.start.slice(0,16),end:c.end.slice(0,16)})">登记</button></td></tr></tbody></table></div><div v-if="coverageEdit.sourceId" class="form-row"><label>有效期开始<input type="datetime-local" v-model="coverageEdit.start"></label><label>有效期结束<input type="datetime-local" v-model="coverageEdit.end"></label><label class="grow">停测区间（每行 开始,结束）<textarea v-model="coverageEdit.stops" placeholder="2026-01-01T00:00,2026-02-01T00:00"></textarea></label><label>说明<input v-model="coverageEdit.note"></label><button @click="confirmCoverage">确认覆盖</button></div></section>
 </template>
 <template v-if="['simulation','calibration'].includes(page)">
  <div class="work-grid"><div><section class="panel"><div class="panel-title"><h3>{{page==='calibration'?'分步自动率定':'建立历史计算方案'}}</h3><span>小时演算 · 日尺度评价</span></div><div class="form-grid"><label class="full">任务名称<input v-model="run.name" placeholder="例如：未率定基线 / 蒸发系数试调"></label><label class="full">真实输入版本<select :value="run.inputId" @change="chooseInput($event.target.value)"><option value="">请选择已登记的真实输入</option><option v-for="i in boot.inputs" :value="i.id" :disabled="i.compatible===false">{{i.name}} · {{i.manifest.start.slice(0,10)}}—{{i.manifest.end.slice(0,10)}}</option></select></label><label>北京时间起始<input type="datetime-local" step="3600" v-model="run.start"></label><label>北京时间结束<input type="datetime-local" step="3600" v-model="run.end"></label><template v-if="page==='calibration'"><label>率定阶段<select v-model="run.stage"><option value="runoff">产汇流：杜加日流量</option><option value="lake">湖泊：主站日湖位</option></select></label><label>评价次数预算<input type="number" min="10" max="2000" v-model.number="run.maxEvaluations"></label><label v-if="run.stage==='lake'" class="full">冻结流域参数的基准成果<select v-model="run.baseTaskId"><option value="">请选择同输入版本成果</option><option v-for="t in completed" :value="t.id">{{t.name||t.id}}</option></select></label><p class="note full">只搜索 2024 年；2023 年连续预热，2025 年独立验证。冰雪参数先固定；湖泊阶段只搜索蒸发转换系数。</p></template></div><div class="actions"><button class="primary" :disabled="busy||!run.inputId" @click="submit(page==='calibration'?'calibration':'simulation')">{{page==='calibration'?'开始自动率定':'开始历史模拟'}}</button><button v-if="page==='simulation'" :disabled="busy||!run.inputId" @click="submit('trial')">人工试调运行</button></div><p v-if="!run.inputId" class="note warning">当前没有真实气象输入，请先在“模型与资料”登记。</p></section><section class="panel"><div class="panel-title"><h3>方案与参数版本</h3></div><div class="form-row"><label class="grow">命名方案<input v-model="schemeName" placeholder="保存当前输入、时段和参数"></label><button @click="saveScheme">保存方案</button></div><div class="saved-list"><button v-for="s in boot.schemes" @click="Object.assign(run,s.payload);Object.assign(params,s.payload.parameters||{});notice='已恢复方案'">{{s.name}}</button></div><div class="form-row"><label class="grow">命名参数<input v-model="paramName" placeholder="未率定初值或试调成果"></label><button @click="saveParameters">保存参数</button></div><div class="saved-list"><button v-for="p in boot.parameters" @click="Object.assign(params,p.payload.parameters);notice='已恢复参数版本'">{{p.name}}</button></div></section></div><section class="panel"><div class="panel-title"><h3>模型参数</h3><button class="link" @click="Object.assign(params,boot.defaultParameters)">恢复通用初值</button></div><p class="note">默认值未率定。面积及实测起始湖位固定；不包含冻土参数。</p><div class="parameter-list"><label v-for="d in boot.parameterDefinitions"><span>{{d.label}}<small>{{d.key}} · {{d.unit||'无量纲'}}</small></span><input type="number" :min="d.min" :max="d.max" :step="d.step" v-model.number="params[d.key]"></label></div></section></div>
 </template>
 <template v-if="page==='results'">
  <section class="panel"><div class="panel-title"><h3>计算成果与后台任务</h3><label class="toggle"><input type="checkbox" v-model="trash">平台回收站</label></div><div class="table-wrap"><table><thead><tr><th>名称 / 编号</th><th>类型</th><th>状态 / 进度</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="t in listed" :key="t.id"><td><button class="link" @click="openTask(t.id)">{{t.name||t.id}}</button><small class="block">{{t.message}}</small></td><td>{{t.kind}}</td><td><span class="badge" :class="{warning:t.status==='failed'}">{{status(t.status)}}</span> {{number(t.progress,0)}}%</td><td>{{t.created_at.slice(0,19).replace('T',' ')}}</td><td><button v-if="['queued','running','stopping'].includes(t.status)" @click="stop(t.id)">停止</button><template v-else><button @click="metadata(t,{favorite:!t.favorite})">{{t.favorite?'★':'☆'}}</button><button @click="metadata(t,{trashed:!t.trashed})">{{t.trashed?'恢复':'移入回收站'}}</button><button v-if="t.trashed" @click="previewCleanup(t)">清理预览</button></template></td></tr><tr v-if="!listed.length"><td colspan="5" class="empty">没有计算记录</td></tr></tbody></table></div></section>
  <section v-if="cleanup" class="panel"><h3>Windows 回收站清理预览</h3><p>{{cleanup.files.length}} 个文件 · {{number(cleanup.bytes/1024/1024)}} MB</p><pre>{{cleanup.files.map(f=>f.path).join('\n')}}</pre><p class="warning" v-if="cleanup.protected.length">受保护引用：{{cleanup.protected.join('、')}}</p><button :disabled="cleanup.protected.length>0" @click="executeCleanup">确认移入 Windows 回收站</button><button @click="cleanup=null">取消</button></section>
 </template>
 <template v-if="page==='process'"><section class="panel"><div class="panel-title"><h3>连续计算状态</h3><span>雪水当量、冰川调蓄、土壤水、子流域与湖泊状态</span></div><div class="table-wrap"><table><thead><tr><th>有效时刻</th><th>名称 / 来源</th><th>平均雪水当量</th><th>操作</th></tr></thead><tbody><tr v-for="s in states"><td>{{s.valid_at}}</td><td>{{s.name||s.id}}</td><td>{{number(s.summary.sweMean)}} mm</td><td><button @click="resume(s)">选择续算</button><button @click="action(async()=>{const name=prompt('状态名称',s.name);if(name!==null){await api('states/'+s.id,{name,favorite:true});await refresh()}})">命名保留</button></td></tr><tr v-if="!states.length"><td colspan="4" class="empty">成功完成历史计算后生成状态</td></tr></tbody></table></div><div v-if="selectedState" class="form-row"><label>续算起始<input type="datetime-local" v-model="run.start"></label><label>续算结束<input type="datetime-local" v-model="run.end"></label><button class="primary" @click="submit('continuation')">按当前条件续算</button></div></section><section class="panel"><div class="form-row"><label class="grow">过程成果<select :value="detail?.id" @change="openTask($event.target.value)"><option value="">选择成果</option><option v-for="t in completed" :value="t.id">{{t.name||t.id}}</option></select></label><label>计算单元<select v-model="unit" @change="loadProcess"><option v-for="(u,i) in detail?.result?.units||[]" :value="i">{{u.id}}</option></select></label></div><Chart :rows="processRows" :series="[{key:'swe',label:'雪水当量'},{key:'WU',label:'上层张力水'},{key:'WL',label:'下层张力水'},{key:'glacierStorage',label:'冰川调蓄'}]" unit="mm"/></section></template>
 <template v-if="page==='model'"><section class="panel"><div class="panel-title"><h3>资料接入与处理</h3><span>扫描预览 → 校验入库 → 覆盖报告</span></div><div class="form-row"><label>观测文件对应站点<select v-model="uploadStation"><option v-for="s in boot.stations.filter(s=>['SLC','DUJA','BLQ','115DB'].includes(s.id))" :value="s.id">{{s.name}}</option></select></label><label class="grow">Excel / NetCDF / 工作区备份<input type="file" accept=".xls,.xlsx,.nc,.zip" @change="uploadFile=$event.target.files[0]"></label><button @click="upload" :disabled="busy">上传文件</button></div><div class="actions"><button @click="action(previewImport)">扫描观测资料</button><button @click="operation('import-observations')">校验并入库</button><button @click="registerFiles">登记真实气象输入</button><button @click="operation('build-spatial')">重建空间产品</button></div><p class="note">Excel 文件名须包含“雨量”“水位”或“流量”；年度矩阵需包含年份。NetCDF 接受 ERA5-Land tp、t2m、pev；下载工具位于 scripts/download_era5.py。历史资料覆盖不足时不能开展完整年度率定。</p></section><section class="panel"><div class="panel-title"><h3>本地 NetCDF 选择</h3><button class="link" @click="action(loadInputFiles)">刷新文件清单</button></div><p class="note">选择一个连续时段的原始文件登记；不选择时尝试全部文件，存在断档将拒绝登记。上传后刷新清单。</p><div class="saved-list"><label v-for="f in inputFiles"><input type="checkbox" v-model="selectedFiles" :value="f.path">{{f.path.split('/').at(-1)}} · {{number(f.bytes/1024/1024)}} MB</label></div><button @click="registerFiles">登记所选连续气象文件</button></section><section class="panel"><div class="panel-title"><h3>已登记真实输入</h3></div><div v-for="i in boot.inputs" class="input-product"><strong>{{i.name}}</strong><code>{{i.id}}</code><p>{{i.manifest.start}} — {{i.manifest.end}} · {{number(i.manifest.hours,0)}} 小时 · {{i.manifest.gridCount}} 格网</p><p class="note">{{i.manifest.assumptions.join('；')}}</p><a class="link" :href="'/api/model/input-qc?inputId='+i.id" target="_blank" rel="noopener">查看站点与格网日、月核对报告 →</a></div><div v-if="!boot.inputs.length" class="empty">尚未登记真实气象输入</div><div class="form-row"><label class="grow">输入过程<select v-model="run.inputId"><option v-for="i in boot.inputs" :value="i.id" :disabled="i.compatible===false">{{i.name}} · {{i.manifest.start.slice(0,10)}}—{{i.manifest.end.slice(0,10)}}</option></select></label><button @click="loadClimate" :disabled="!run.inputId">查看真实气象过程</button></div><p class="note">降水和蒸发为湖面面积加权基准；气温为计算单元均值，尚未高程修正。</p><Chart :rows="climateRows" :series="[{key:'precipitation',label:'湖面降水',type:'bar'},{key:'evaporation',label:'潜在蒸发能力'}]" unit="mm/d"/><Chart :rows="climateRows" :series="[{key:'temperature',label:'气温基准'}]" unit="℃"/></section><section class="panel"><div class="panel-title"><h3>空间与模型条件</h3></div><BasinMap/><div class="table-wrap"><table><thead><tr><th>分区</th><th>陆面面积 km²</th><th>冰川面积 km²</th><th>验证状态</th></tr></thead><tbody><tr v-for="b in boot.spatial?.basins"><td>{{b.name}}</td><td>{{number(b.areaKm2)}}</td><td>{{number(b.glacierAreaKm2)}}</td><td>{{b.id==='zajia'?'杜加内部断面可评价':'未独立验证'}}</td></tr></tbody></table></div><p class="note">面积闭合误差 {{boot.spatial?.areaClosureErrorKm2}} km²。地下水净交换、外流暂按零；冰川范围固定。气温递减参考采用现有 DEM 格网平均高程，待补充 ERA5 地形后可替换。</p></section></template>
 <template v-if="page==='system'"><section class="panel"><div class="panel-title"><h3>独立工作区</h3></div><dl><dt>项目标识</dt><dd>selinco</dd><dt>运行目录</dt><dd>{{system?.workspace||'正在读取'}}</dd><dt>默认服务端口</dt><dd>8879</dd><dt>SQLite 记录</dt><dd>{{system?.database}}</dd><dt>HDF5 运行库</dt><dd>{{system?.hdf5Version}}</dd></dl><p class="note">升级和卸载保留用户工作区。备份包含数据库、来源快照、输入、成果和状态；恢复到新目录，不覆盖当前资料。</p><div class="actions"><button class="primary" @click="backup" :disabled="active.length>0">备份并下载</button><button @click="navigate('model')">上传备份 / 资料</button><button @click="action(async()=>{await api('shutdown',{});notice='服务已退出，可关闭本页面'})" :disabled="active.length>0">退出平台服务</button></div></section><section v-if="restorePreview" class="panel"><h3>备份恢复预览</h3><p>{{restorePreview.files}} 个文件 · {{number(restorePreview.bytes/1024/1024)}} MB；将校验摘要并恢复到独立目录。</p><button class="primary" @click="restore">确认恢复</button></section><section class="panel"><h3>资料与计算边界</h3><p>第一版提供真实历史资料管理、冰雪新安江产汇流与定面积湖位演算。实时数据与未来气象未接入时不会生成预报曲线。</p><p class="note">软件流程通过与模型效果达标分别验收。2025 年为独立验证，2026 年仅在实际覆盖范围内延伸检查。</p></section></template>
 <section v-if="detail&&['results','simulation','calibration'].includes(page)" class="panel"><div class="panel-title"><h3>{{detail.name||detail.id}}</h3><span class="badge">{{status(detail.status)}}</span><button class="link" @click="detail=null">收起 ×</button></div><button v-if="detail.request?.parameters" @click="restoreRequest">恢复输入、参数和时段</button><p v-if="!detail.result">{{detail.message||'等待计算'}} · {{number(detail.progress,1)}}%</p><template v-if="detail.result?.daily"><div class="actions"><button @click="useResult">恢复参数 / 用作湖泊率定基准</button><a class="button" :href="exportUrl('daily.csv')">导出日过程 CSV</a><a class="button" :href="exportUrl('hourly.npz')">导出逐时数据</a><a class="button" :href="exportUrl('checkpoint.json')">导出状态</a><label class="inline">比较成果<select @change="action(async()=>{compare=$event.target.value?await api('tasks/'+$event.target.value):null})"><option value="">不比较</option><option v-for="t in completed.filter(t=>t.id!==detail.id)" :value="t.id">{{t.name||t.id}}</option></select></label></div><p v-if="detail.result.daily.every(r=>r.lakeLevel==null)" class="note warning">所选时段没有可续接的湖位起点；流域计算已完成，湖位需从可靠观测窗口起点回放或使用同条件父状态。</p><Chart :rows="comparedRows" :series="compare?[...resultSeries,{key:'comparedLake',label:'比较成果湖位'}]:resultSeries" unit="m"/><Chart :rows="comparedRows" :series="[{key:'duja',label:'杜加模拟'},{key:'observedFlow',label:'杜加实测'},{key:'total',label:'总入湖流量'},...(compare?[{key:'comparedFlow',label:'比较成果杜加'}]:[])]" unit="m³/s"/><Chart :rows="comparedRows" :series="[{key:'zajia',label:'扎加藏布入湖'},{key:'zagen',label:'扎根藏布入湖'},{key:'boqu',label:'波曲藏布入湖'},{key:'ali',label:'阿里藏布入湖'},{key:'fringe',label:'湖周来水'}]" unit="m³/s"/><Chart :rows="comparedRows" :series="[{key:'lakeRainMm',label:'湖面降水',type:'bar'},{key:'lakeEvaporationMm',label:'湖面蒸发',type:'bar'},{key:'snowmeltMm',label:'融雪补给'},{key:'icemeltMm',label:'融冰补给'}]" unit="mm/d"/><div class="table-wrap"><table><thead><tr><th>年份 / 用途</th><th>流量样本</th><th>NSE</th><th>KGE</th><th>PBIAS %</th><th>湖位样本</th><th>RMSE m</th><th>MAE m</th><th>偏差 m</th></tr></thead><tbody><tr v-for="(m,y) in detail.result.metrics"><td>{{y}} / {{m.purpose}}</td><td>{{m.flow.count}}</td><td>{{number(m.flow.nse,3)}}</td><td>{{number(m.flow.kge,3)}}</td><td>{{number(m.flow.pbias)}}</td><td>{{m.lake.count}}</td><td>{{number(m.lake.rmse,3)}}</td><td>{{number(m.lake.mae,3)}}</td><td>{{number(m.lake.bias,3)}}</td></tr></tbody></table></div><p v-if="detail.result.calibration" class="note">搜索 {{detail.result.calibration.evaluations}} 次 · {{detail.result.calibration.termination==='converged'?'达到收敛条件':'预算耗尽'}} · 只使用2024年观测</p><details><summary>水量守恒与方案假设</summary><pre>{{JSON.stringify(detail.result.diagnostics,null,2)}}</pre></details><div class="form-row"><label class="grow">成果命名<input :value="detail.name" @change="metadata(detail,{name:$event.target.value})"></label><label class="grow">备注<input :value="detail.notes" @change="metadata(detail,{notes:$event.target.value})"></label><label>成果分组<input :value="detail.collection" @change="metadata(detail,{collection:$event.target.value})"></label></div></template><pre v-else-if="detail.result">{{JSON.stringify(detail.result,null,2).slice(0,10000)}}</pre></section>
 </template><footer>色林错预警预报平台 <span>真实资料 · 条件冻结 · 结果可复算</span></footer></div>
 </main>
</div>
</template>
